interface Renderer {
    void renderCircle(float radius);
    void renderSquare(float side);
}

final class VectorRenderer implements Renderer {
    public void renderCircle(float radius) {
        System.out.println("vector circle r=" + radius);
    }
    public void renderSquare(float side) {
        System.out.println("vector square s=" + side);
    }
}

final class RasterRenderer implements Renderer {
    public void renderCircle(float radius) {
        System.out.println("raster circle r=" + radius);
    }
    public void renderSquare(float side) {
        System.out.println("raster square s=" + side);
    }
}

abstract class Shape {
    protected final Renderer renderer;
    protected Shape(Renderer renderer) {
        if (renderer == null) throw new IllegalArgumentException("renderer required");
        this.renderer = renderer;
    }
    abstract void draw();
}

final class Circle extends Shape {
    private final float radius;
    Circle(float radius, Renderer renderer) {
        super(renderer);
        this.radius = radius;
    }
    @Override void draw() {
        // Abstraction-side logic stays here: culling, transforms.
        if (radius <= 0) return;
        renderer.renderCircle(radius); // delegation: the bridge
    }
}

final class Client {
    public static void main(String[] args) {
        Shape v = new Circle(2.0f, new VectorRenderer());
        Shape r = new Circle(2.0f, new RasterRenderer());
        v.draw();
        r.draw(); // same abstraction, swapped implementation at runtime
    }
}
